template=read('audit/runs/next-shard-0024-active-template.json')
assert set(rows)=={r['questionId'] for r in template['reviews']}
for r in template['reviews']:
    i=r['questionId']; src,premise,reasons=rows[i]; ids=src.split()
    r.update(checks=['singleAnswer','context','wording','noGiveaway','distinctFact','category','difficulty','scope'],
      notes='Read all four options, full topic digests and cross-bank comparisons. '+premise,
      context='Original English-language theatrical film; named sequel where specified. Bounded scene or character/credit identity as stated.',
      timeSensitive=False,nextReviewAt=None)
    r['premise']={'reason':premise,'sources':ids}
    for n,(o,reason) in enumerate(zip(r['options'],reasons)):
        o.update(basis='direct' if n==0 else 'exclusive-inference',reason=reason,sources=ids)
    r['challenge']={'reviewer':'Codex','at':'2026-11-08','premiseChecked':True,'alternativesExcluded':True,
      'notes':'Separate final-wording challenge: '+' '.join(reasons[1:])+' The cited scene/identity establishes the premise and only option 0 fits this bounded wording.'}
template['sourcesChecked']=sorted({s for r in template['reviews'] for s in r['premise']['sources']})
write('audit/runs/next-shard-0024-evidence-notes.json',template)
print('Authored',len(rows),'explicit reviews; source library updated. No ledger import performed.')
